  have Ah := MIPStarRE.LDT.GlobalVariance.pointConditionedOutcomeOperatorAtPolynomial params strategy h u;
  Ah * (MIPStarRE.LDT.SelfImprovement.sandwichedPolynomialSubMeasAt params strategy T u).outcome h' * Ah = if h.toFun u = h'.toFun u then (MIPStarRE.LDT.SelfImprovement.sandwichedPolynomialSubMeasAt params strategy T u).outcome h' else 0

